// Research-only alternative responsibility route; no live student import.
import {explorerResults as baseline,explorerCareerQuestions as priorQuestions} from './open-explorer-088.js';
import{plantResearchQuestion}from'./plant-science-090.js';
export{plantResearchQuestion};
const plant='degree-19101300',advice=plant+'-047-responsibility';
const eligible=a=>!!a&&!a.reviewHold&&(a.source!=='profile-inferred'||(['high','medium'].includes(a.confidence)&&!!a.evidence?.trim()));
export const explorerCareerQuestions=id=>id===plant?[...priorQuestions(id),plantResearchQuestion]:priorQuestions(id);
export function explorerResults(s){const b=baseline(s);return {...b,version:'0.90-research',rows:b.rows.map(r=>{if(r.id!==plant||r.specific.supported||r.specific.contrary.some(c=>c.questionId!==advice)||!r.specific.missing.some(q=>q.id===advice))return r;const original=s.explorer053?.professionAnswers?.[plant]?.[advice]||s.profileJourney?.expandedInterests?.[advice];if(original?.reviewHold)return r;
const a=s.explorer053?.professionAnswers?.[plant]?.[plantResearchQuestion.id],yes=eligible(a)&&a.response==='yes';const evidence=[...r.specific.evidence],contrary=r.specific.contrary.filter(c=>c.questionId!==advice),domains=new Set(r.specific.specificDomains);if(yes){domains.add('responsibility');evidence.push({questionId:plantResearchQuestion.id,prompt:plantResearchQuestion.prompt,domain:'responsibility',text:plantResearchQuestion.prompt,source:a.source,confidence:a.confidence,evidence:a.evidence,kind:'specific'});}if(eligible(a)&&a.response==='no')contrary.push({questionId:plantResearchQuestion.id,prompt:plantResearchQuestion.prompt,source:a.source,evidence:a.evidence});const missing=r.specific.missing.filter(q=>q.id!==advice);if(!yes)missing.push(plantResearchQuestion);return {...r,band:domains.size===3&&!contrary.length?'Specific interests supported':r.band,specific:{...r.specific,declinedResponsibilityRoutes:original?.response==='no'?['grower-advising']:[],responsibilityRoute:yes?'research-reporting':'research-unconfirmed',inferred:r.specific.inferred||yes&&a.source==='profile-inferred',supported:domains.size===3&&!contrary.length,contrary,evidence,specificDomains:[...domains],missing,asked:r.specific.asked+(a?1:0),requirement:'Subject and method plus either the original grower-advising responsibility or independently supported research/documentation/reporting responsibility.'}};})};}
